INSERT INTO sources (source_id, source_type, title, scope) VALUES
  ('SRC_HENKELMAN_ELAM','secondary scholarship','Wouter F. M. Henkelman, The Other Gods Who Are: Studies in Elamite-Iranian Acculturation (Achaemenid History XIV, NINO 2008)','Elamite')
INSERT INTO _e VALUES
 ('ENT_MES_HENDURSAGA','Hendursaga','Mesopotamian','God','Deity','night watch; heralds; law and order; protection of streets','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Divine night-watchman and ''chief herald,'' attested in the Lagash pantheon from the Early Dynastic period and later equated with Akkadian Ishum.'),
 ('ENT_MES_NINEGAL','Ninegal','Mesopotamian','Goddess','Tutelary','palaces; royal dynasty; protection of kingship','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','''Lady of the Palace'' (Akk. Belet-ekallim); oldest attestation is the Early Dynastic Fara god list, later guardian of the royal dynasty across Mesopotamia, Mari and the Hittite world.'),
 ('ENT_MES_NIN_MARKI','Nin-MAR.KI','Mesopotamian','Goddess','Tutelary','cattle; oaths; long-distance trade; coastal Lagash','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Divine protector of cattle and oath-deity in the Lagash pantheon, daughter of Nanshe and Nindara, with chief cult center at the sea-port Guabba; attested in Early Dynastic Lagash.'),
 ('ENT_MES_LISIN','Lisin','Mesopotamian','Goddess','Deity','motherhood; later fire; lamentation','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Originally a goddess addressed as ''mother,'' the final deity praised in the Early Dynastic Zame Hymns as tutelary of Abu Salabikh; daughter of Shulpae and Ninhursag.'),
 ('ENT_MES_NINSIKILA','Ninsikila','Mesopotamian','Deity','Deity','purity; consort cult of Lisin','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Spouse of Lisin, male in Early Dynastic sources (Zame Hymns) before a later gender reversal; distinct from the homophonous Dilmunite goddess Meskilak.'),
 ('ENT_MES_ASHGI','Ashgi','Mesopotamian','God','Tutelary','war; tutelary of Adab and Kesh','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Warrior god and original tutelary of Adab, son of Ninhursag and Shulpae, already named in Early Dynastic sources from Fara and the Kesh Temple Hymn.'),
 ('ENT_MES_PANIGINGARRA','Panigingarra','Mesopotamian','God','Deity','wisdom; scholarship; tutelary of Adab','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Son of Ninhursag and Shulpae worshiped at Adab and associated with his brother Ashgi; attested from the Early Dynastic period and later equated with Ninurta.'),
 ('ENT_MES_PABILSAG','Pabilsag','Mesopotamian','God','Deity','warrior; healing (by marriage); judiciary','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Warrior god first attested in the Early Dynastic IIIa god lists from Fara and Abu Salabikh; husband of the healing goddess Ninisina and father of Damu and Gunura.'),
 ('ENT_MES_NINISINA','Ninisina','Mesopotamian','Goddess','Deity','healing; medicine; tutelary of Isin','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','''Lady of Isin,'' great divine physician first attested in the Fara god lists of the Early Dynastic IIIa period; wife of Pabilsag, later syncretized with Gula.'),
 ('ENT_MES_GUNURA','Gunura','Mesopotamian','Goddess','Deity','healing; lamentation','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Daughter of Ninisina and Pabilsag and sister of the dying healer-god Damu, attested as part of the Isin healing-goddess circle.'),
 ('ENT_MES_GATUMDUG','Gatumdug','Mesopotamian','Goddess','Tutelary','motherhood; tutelary of Lagash; kingship','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Tutelary goddess of Lagash described metaphorically as its mother in Early Dynastic sources, later honored by Gudea who called her his mother and father.'),
 ('ENT_MES_DUMUZI_ABZU','Dumuzi-abzu','Mesopotamian','Goddess','Tutelary','fertility; freshwater abzu; tutelary of Kinunir','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Tutelary goddess of Kinunir near Lagash (also called Kinirša), a female counterpart to Dumuzi attested in the Early Dynastic Lagash state pantheon.'),
 ('ENT_MES_NINDARA','Nindara','Mesopotamian','God','Deity','warrior; ''tax-collector of the sea''; Lagash','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Local Lagash god and husband of Nanshe, attested in the Early Dynastic Lagash pantheon; Selz regards him as elder brother of Hendursaga.'),
 ('ENT_MES_IGALIMA','Igalima','Mesopotamian','God','Deity','doorkeeping; justice; sons of Ningirsu','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Son of Ningirsu and Bau, the divine ''door of the throne-room''/E-ninnu, receiving offerings already in Early Dynastic Lagash and named on the Gudea cylinders.'),
 ('ENT_MES_SHULSHAGA','Shulshaga','Mesopotamian','God','Deity','sons of Ningirsu; Lagash cult','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Eldest son of Ningirsu and Bau and elder brother of Igalima, attested receiving offerings in Early Dynastic Lagash documents.'),
 ('ENT_MES_SHUL_UTULA','Shul-utula','Mesopotamian','God','Tutelary','personal/family deity; intercession; royal luck','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','''Youngling shepherd,'' personal god of the Ur-Nanshe dynasty of Lagash, named in Early Dynastic royal inscriptions of Eannatum and Entemena.'),
 ('ENT_MES_LUGAL_MARADA','Lugal-Marada','Mesopotamian','God','Tutelary','earth; the plow; tutelary of Marad; war','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','City god of Marad, sometimes a manifestation of Ninurta; subject of one of the Temple Hymns, with cult attested from the 3rd millennium.'),
 ('ENT_MES_GIBIL_GIRRA','Gibil','Mesopotamian','God','Deity','fire; light; metallurgy; ritual purification','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Fire god (Akk. Girra), patron of metalworkers and purification, with earliest attestations in Early Dynastic III administrative texts from Fara and Telloh.'),
 ('ENT_MES_NINILDU','Ninildu','Mesopotamian','God','Deity','carpentry; craft','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Divine carpenter worshiped at Zabalam, attested in the god lists from Abu Salabikh and Fara and in the Early Dynastic Zame Hymns.'),
 ('ENT_MES_NINMUG','Ninmug','Mesopotamian','Goddess','Deity','metalworking; craft; birth','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Divine metalworker/sculptor (''tibira kalamma'') and birth-helper of Ninmah, attested in the Early Dynastic Fara god list with cult at Kisiga and Adab.'),
 ('ENT_MES_NINIMMA','Ninimma','Mesopotamian','Goddess','Deity','scribal arts; scholarship; birth assistance','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Divine scholar/scribe and courtier of Enlil who also assisted at birth; attested among the early Nippur circle and in Enki and Ninmah.'),
 ('ENT_MES_NINKURRA','Ninkurra','Mesopotamian','Goddess','Deity','sculpture; stone-working; craft','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Divine artisan/sculptor of the Enki–Ninhursag generative sequence, mother of Uttu in the Dilmun myth tradition.'),
 ('ENT_MES_NINSHAR','Ninshar','Mesopotamian','Goddess','Deity','vegetation; craft; birth assistance','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Goddess of the Enki–Ninhursag and Enki–Ninmah birth-helper circle; the theophoric name Ur-Ninšar is common in Early Dynastic and Ur III sources.'),
 ('ENT_MES_NINNIGARA','Ninnigara','Mesopotamian','Goddess','Deity','birth; healing; the niĝar shrine','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Goddess of the niĝar (a birth/temple precinct) linked to birth and healing, attested in the Fara god list and the Early Dynastic Zame Hymns.'),
 ('ENT_MES_NINGIRIMA','Ningirima','Mesopotamian','Goddess','Deity','incantations; ritual purification; snakes; sacred water','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Major Early Dynastic incantation goddess and divine purifier associated with snakes and sacred-water basins, central to the earliest Sumerian magical tradition.'),
 ('ENT_MES_MES_SANGA_UNUG','Mes-sanga-Unug','Mesopotamian','God','Tutelary','war; tutelary of Kullaba (Uruk)','A','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Warrior god of Uruk''s Kullaba district, ''great ensi of Inanna,'' belonging to the earliest Uruk pantheon and named in the Early Dynastic Zame Hymns.'),
 ('ENT_MES_NINIRIGAL','Ninirigal','Mesopotamian','Goddess','Tutelary','tutelary of Kullaba (Uruk)','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Tutelary goddess of Uruk''s Kullaba district, counted among the chief deities praised in the opening Early Dynastic hymns.'),
 ('ENT_MES_NIRAH','Nirah','Mesopotamian','God','Deity','serpents; divine messenger; Der cult','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Serpent god and messenger of Ishtaran of Der, depicted as a snake; worship attested from the late Early Dynastic period.'),
 ('ENT_MES_NINGIRIDA','Ningirida','Mesopotamian','Goddess','Deity','underworld (by association); chthonic family of Ninazu','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Wife of the chthonic god Ninazu and mother of Ningishzida, appearing alongside Ninazu from the Ur III period.'),
 ('ENT_MES_NINURA','Ninura','Mesopotamian','Goddess','Tutelary','tutelary of Umma; consort cult of Shara','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Goddess of the Umma region and wife of Shara, attested only in third-millennium sources before being displaced by Inanna of Zabalam.'),
 ('ENT_MES_NINTI','Ninti','Mesopotamian','Goddess','Deity','the rib / life (''lady of life''); healing','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','''Lady of the rib/life,'' one of the eight healing deities born of Ninhursag in the Dilmun myth; attested near Ninkasi in a Fara-period document.'),
 ('ENT_MES_NUNGAL','Nungal','Mesopotamian','Goddess','Deity','prisons; judgment; underworld','B','Archaic Sumerian / Early Dynastic deity (earliest god-lists: Fara, Abu Salabikh, Zame Hymns)','Goddess of prisons and divine sifter of the guilty from the innocent, a daughter-in-law of Enlil whose name is attested already in the Early Dynastic period.'),
 ('ENT_EGY_BAT','Bat','Egyptian','Goddess','Cow/sky tutelary goddess','sky; cattle; cosmic protection; nome tutelary','A','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Archaic bovine sky-goddess of the 7th Upper Egyptian nome, depicted as the inward-curling-horned cow head atop the Narmer Palette (Dyn. 0/1) and later absorbed by Hathor.'),
 ('ENT_EGY_MEHIT','Mehit','Egyptian','Goddess','Lioness goddess','lioness ferocity; nome tutelary; consort of Anhur','A','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Lioness goddess of This/Thinis whose recumbent-lioness emblem is attested already in the Early Dynastic period; consort of Anhur (Onuris).'),
 ('ENT_EGY_SED','Sed','Egyptian','God','Canine/jackal kingship deity','royal jubilee (heb-sed); protection of the king; canine power','B','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Archaic jackal/wolf-form deity for whom the royal Sed (jubilee) festival is named, attested from the 1st Dynasty and associated with Wepwawet.'),
 ('ENT_EGY_DUNANWI','Dunanwi','Egyptian','Tutelary deity','Falcon nome god','falcon kingship; nome tutelary; eastern sky','B','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Falcon tutelary of the 18th Upper Egyptian nome, named in the Pyramid Texts and later largely assimilated to Horus.'),
 ('ENT_EGY_KHENTYIRTY','Khenty-irty','Egyptian','God','Falcon god of Letopolis','sight and blindness (sun and moon eyes); guardianship; kingship','B','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Falcon god of Letopolis appearing as Khenty-irty (''Foremost of the Two Eyes'')/Khenty-khety; attested from the Old Kingdom and linked to the waxing and waning of celestial light.'),
 ('ENT_EGY_SEPA','Sepa','Egyptian','Protective deity','Centipede god','protection against venomous bites; soil fertility; funerary protection','B','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Centipede god of Heliopolis invoked against venomous creatures; attested from the Old Kingdom and later identified with Osiris.'),
 ('ENT_EGY_HEDEDET','Hededet','Egyptian','Goddess','Scorpion goddess','scorpion protection; healing of stings; maternal protection','B','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Scorpion goddess named in the Pyramid Texts, a protective scorpion power later assimilated to Isis.'),
 ('ENT_EGY_KHENTIKHETI','Khenti-kheti','Egyptian','Tutelary deity','Crocodile/falcon god of Athribis','nome tutelary; kingship; protection','B','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Local god of Athribis (10th Lower Egyptian nome), originally crocodile-form and later falcon-form (Horus-Khenti-kheti), attested from the Old Kingdom.'),
 ('ENT_EGY_SOULS_OF_PE','Souls of Pe','Egyptian','Collective','Ancestral royal souls (Lower Egypt)','deceased predynastic kings of Buto; royal ancestors; jubilation for the king','A','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Falcon-headed ancestral spirits of the predynastic rulers of Pe (Buto) in the Delta, invoked acclaiming the king in the Pyramid Texts.'),
 ('ENT_EGY_SOULS_OF_NEKHEN','Souls of Nekhen','Egyptian','Collective','Ancestral royal souls (Upper Egypt)','deceased predynastic kings of Hierakonpolis; royal ancestors; jubilation for the king','A','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Jackal-headed ancestral spirits of the predynastic rulers of Nekhen (Hierakonpolis) in Upper Egypt, paired with the Souls of Pe in the Pyramid Texts.'),
 ('ENT_EGY_IABET','Iabet','Egyptian','Goddess','Personification of the East','the eastern direction; sunrise; purification','B','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Goddess personifying the East (Iabtet), counterpart of Imentet the West, attested from the Old Kingdom and associated with the rising sun.'),
 ('ENT_EGY_IMENTET','Imentet','Egyptian','Goddess','Personification of the West / necropolis','the western direction; the necropolis; welcoming the dead','B','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Goddess of the West and the realm of the dead, wearing the West (imnt) emblem on her head, attested from the Old Kingdom and closely linked to Hathor.'),
 ('ENT_EGY_NEBETHETEPET','Nebethetepet','Egyptian','Goddess','Female creative principle of Atum','creation (hand of Atum); Heliopolitan generative power; satisfaction','B','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Heliopolitan goddess (''Mistress of the Offering/Contentment'') personifying the creative hand of Atum, associated with Iusaaset and Hathor from the Old Kingdom onward.'),
 ('ENT_EGY_IUNIT','Iunit','Egyptian','Goddess','Theban/Hermonthis consort goddess','nome tutelary; consort of Montu; the town of Iuni/Hermonthis','C','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Local goddess of Hermonthis/Armant (Iuni), a consort of Montu in the Theban region, attested from the Middle Kingdom.'),
 ('ENT_EGY_HENKHISESUI','Henkhisesui','Egyptian','God','East-wind deity','the east wind; weather; cardinal-wind personification','C','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Personification of the east wind, one of the cardinal-wind deities, attested as a ram- or scarab-form figure and linked to Anhur.'),
 ('ENT_EGY_SERET','Seret','Egyptian','Goddess','Lioness nome goddess','lioness power; nome tutelary; protection','C','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Lioness goddess associated with a Delta locality, one of the archaic feline tutelaries grouped with Bastet and Sekhmet.'),
 ('ENT_EGY_AHA','Aha','Egyptian','Protective deity','Apotropaic dwarf/lion protector','household and birth protection; warding evil; combat with serpents','B','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','Aha (''the Fighter''), a leonine-dwarf apotropaic deity depicted strangling serpents on Middle Kingdom ''magic wands'', an early antecedent of Bes.'),
 ('ENT_EGY_SEFKHETABWY','Sefkhet-Abwy','Egyptian','Goddess','Goddess of writing and measurement','writing; building measurement; royal records; counting years of reign','B','Predynastic / Early Dynastic / Old Kingdom Egyptian deity','''She of the Seven Horns'', a form/aspect of the writing goddess associated with the foundation-ceremony ''stretching of the cord'', attested from the Old Kingdom alongside Seshat.'),
 ('ENT_ELAM_PINIKIR','Pinikir','Elamite','Goddess','Astral / Venus deity','heaven; love; the planet Venus; sovereignty','A','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Great early Elamite astral goddess titled ''mistress of heaven''; appears in the Old Elamite treaty of Naram-Sin and at Tchoga Zanbil, equated with Ishtar/Ninsianna in god lists.'),
 ('ENT_ELAM_SIMUT','Simut','Elamite','God','Herald / warrior deity','heraldry of the gods; war; the planet Mars','A','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Elamite herald-god (''god of Elam''), spouse of Manzat, equated with Mesopotamian Nergal and the planet Mars; widely attested in royal inscriptions and An=Anum.'),
 ('ENT_ELAM_NAHHUNTE','Nahhunte','Elamite','God','Solar deity','the sun; justice; law; commerce','A','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Elamite sun god and guarantor of justice/contracts, counterpart of Mesopotamian Shamash; element in many royal names (e.g. Šutruk-Nahhunte) and attested from Susa.'),
 ('ENT_ELAM_MANZAT','Manzat','Elamite','Goddess','Atmospheric / astral deity','the rainbow; the sky','A','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Rainbow goddess shared between Elam and Mesopotamia; in Elam wife of Simut, worshipped at Susa and Der; attested in Middle Elamite royal inscriptions.'),
 ('ENT_ELAM_RUHURATER','Ruhurater','Elamite','Creator deity','Local high god','creation; tutelary lordship of Huhnur','B','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Creator god whose cult centre was Huhnur; attested from an Ur III inscription of Amar-Sin and in Middle Elamite texts, regarded as a fashioner of humankind.'),
 ('ENT_ELAM_HUTRAN','Hutran','Elamite','God','Dynastic / warrior deity','war; royal protection','B','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Son of Napirisha and Kiririsha in the Tchoga Zanbil / Anshanite theology; invoked in Middle Elamite royal inscriptions for protection of the king.'),
 ('ENT_ELAM_LAGAMAL','Lagamal','Elamite','Underworld deity','Chthonic / judgment deity','the underworld; judgment of the dead','A','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Underworld god of Susa (also worshipped at Mesopotamian Dilbat); in Susian funerary texts the ''advocatus diaboli'' who, with Ishmekarab, attends Inshushinak''s judgment of souls.'),
 ('ENT_ELAM_ISHMEKARAB','Ishmekarab','Elamite','Underworld deity','Justice / judgment deity','justice; law; judgment of the dead','A','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Deity of justice (''he/she has heard the prayer''); in Susian afterlife texts the ''advocatus dei'' who, with Lagamal, escorts the soul before the judge Inshushinak; attested at Susa and Tchoga Zanbil.'),
 ('ENT_ELAM_NARUNDI','Narundi','Elamite','Goddess','Warrior / victory deity','victory; war; protection','A','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Victory goddess worshipped at Susa c. 2250-1800 BCE (statue dedicated by Puzur-Inshushinak); in Mesopotamian An=Anum reckoned sister of the Sebitti, the ''divine seven of Elam''.'),
 ('ENT_ELAM_NAPRATEP','Napratep','Elamite','Deity','Collective protective deities','protection; creation of life','B','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Group of ''creator/protector gods'' invoked in Middle Elamite royal inscriptions, notably those of Untash-Napirisha at Tchoga Zanbil.'),
 ('ENT_ELAM_SIASHUM','Siashum','Elamite','Goddess','Local deity','local tutelary cult','B','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Goddess receiving a dedicated chapel/inscription in the sacred precinct of Tchoga Zanbil (Dur-Untash) under Untash-Napirisha.'),
 ('ENT_ELAM_KILAH_SHUPIR','Kilah-shupir','Elamite','God','Local deity','local tutelary cult','B','Elamite deity (Susa / Anshan / Tchoga Zanbil)','God honoured by a dedicatory inscription in the Tchoga Zanbil temple complex of Untash-Napirisha.'),
 ('ENT_ELAM_UPURKUBAK','Upurkubak','Elamite','Goddess','Local deity','local tutelary cult','B','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Goddess with a dedicated chapel at Tchoga Zanbil; named in Middle Elamite inscriptions of Untash-Napirisha.'),
 ('ENT_ELAM_HISHMITIK','Hishmitik','Elamite','Deity','Local deity','local tutelary cult','B','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Deity worshipped (frequently paired with Ruhurater) in the Tchoga Zanbil precinct of Untash-Napirisha.'),
 ('ENT_ELAM_TEPTI','Tepti / Temti','Elamite','God','Divine title / lordship','lordship; sovereignty','B','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Elamite ''lord'' (tepti/temti) used as a divine epithet and theophoric element (e.g. Tepti-ahar, Temti-Agun) in Sukkalmah- and Middle-Elamite royal names and inscriptions.'),
 ('ENT_ELAM_JABRU','Jabru','Elamite','God','Sky / high god (Mesopotamian view of Elam)','the sky; supreme lordship','C','Elamite deity (Susa / Anshan / Tchoga Zanbil)','Listed in Mesopotamian god lists (An=Anum, variant Yabru) as the ''Enlil of Elam''; known only from Mesopotamian texts and not yet attested in indigenous Elamite sources.');
INSERT INTO entities (entity_id,canonical_name,tradition,entity_type,category,primary_domains,cult_scope,evidence_confidence,review_status,inclusion_basis,earth_association_score,chthonic_flag,serpent_flag,short_note)
INSERT INTO _s VALUES
 ('ENT_MES_HENDURSAGA','SRC_BLACK_GREEN_MESO','Krebernik, RlA s.v. ''Hendursaĝa''; Wiggermann, ''The Gods Išum and Ḫendursanga'' (JANER 2010)'),
 ('ENT_MES_NINEGAL','SRC_BLACK_GREEN_MESO','Behrens & Klein, RlA s.v. ''Nin-egal''; Beaulieu studies of Belet-ekallim'),
 ('ENT_MES_NIN_MARKI','SRC_BLACK_GREEN_MESO','Selz, FAOS 1995 (Lagaš pantheon); Krebernik, RlA'),
 ('ENT_MES_LISIN','SRC_BLACK_GREEN_MESO','Krebernik & Lisman, ''The Sumerian Zame Hymns from Tell Abū Ṣalābīḫ'' (2020); Krebernik, RlA s.v. ''Lisin'''),
 ('ENT_MES_NINSIKILA','SRC_BLACK_GREEN_MESO','Krebernik & Lisman, Zame Hymns (2020); Krebernik, RlA'),
 ('ENT_MES_ASHGI','SRC_BLACK_GREEN_MESO','Such-Gutiérrez, Adab studies; Krebernik, RlA s.v. ''Ašgi'''),
 ('ENT_MES_PANIGINGARRA','SRC_BLACK_GREEN_MESO','Krebernik, RlA s.v. ''Pa(p)-nigin-ĝara''; Such-Gutiérrez, Adab studies'),
 ('ENT_MES_PABILSAG','SRC_ORACC','Wiggermann, RlA s.v. ''Pabilsaĝ''; ORACC AMGG ''Pabilsag'''),
 ('ENT_MES_NINISINA','SRC_ORACC','ORACC AMGG ''Ninisinna''; Böck, ''The Healing Goddess Gula'' (2014)'),
 ('ENT_MES_GUNURA','SRC_ORACC','Krebernik, RlA s.v. ''Gunura''; ORACC AMGG ''Ninisinna'''),
 ('ENT_MES_GATUMDUG','SRC_BLACK_GREEN_MESO','Selz, FAOS 1995 (Lagaš pantheon); Edzard, RlA s.v. ''Gatumdug'''),
 ('ENT_MES_DUMUZI_ABZU','SRC_BLACK_GREEN_MESO','Selz, FAOS 1995 (Lagaš pantheon); Krebernik, RlA'),
