INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_MES_HENDURSAGA','PER_MES_EARLY','Divine night-watchman and ''chief herald,'' attested in the Lagash pantheon from the Early Dynastic period and later equated with Akkadian Ishum.'),
 ('ENT_MES_NINEGAL','PER_MES_EARLY','''Lady of the Palace'' (Akk. Belet-ekallim); oldest attestation is the Early Dynastic Fara god list, later guardian of the royal dynasty across Mesopotamia, Mari and the Hittite world.'),
 ('ENT_MES_NIN_MARKI','PER_MES_EARLY','Divine protector of cattle and oath-deity in the Lagash pantheon, daughter of Nanshe and Nindara, with chief cult center at the sea-port Guabba; attested in Early Dynastic Lagash.'),
 ('ENT_MES_LISIN','PER_MES_EARLY','Originally a goddess addressed as ''mother,'' the final deity praised in the Early Dynastic Zame Hymns as tutelary of Abu Salabikh; daughter of Shulpae and Ninhursag.'),
 ('ENT_MES_NINSIKILA','PER_MES_EARLY','Spouse of Lisin, male in Early Dynastic sources (Zame Hymns) before a later gender reversal; distinct from the homophonous Dilmunite goddess Meskilak.'),
 ('ENT_MES_ASHGI','PER_MES_EARLY','Warrior god and original tutelary of Adab, son of Ninhursag and Shulpae, already named in Early Dynastic sources from Fara and the Kesh Temple Hymn.'),
 ('ENT_MES_PANIGINGARRA','PER_MES_EARLY','Son of Ninhursag and Shulpae worshiped at Adab and associated with his brother Ashgi; attested from the Early Dynastic period and later equated with Ninurta.'),
 ('ENT_MES_PABILSAG','PER_MES_EARLY','Warrior god first attested in the Early Dynastic IIIa god lists from Fara and Abu Salabikh; husband of the healing goddess Ninisina and father of Damu and Gunura.'),
 ('ENT_MES_NINISINA','PER_MES_EARLY','''Lady of Isin,'' great divine physician first attested in the Fara god lists of the Early Dynastic IIIa period; wife of Pabilsag, later syncretized with Gula.'),
 ('ENT_MES_GUNURA','PER_MES_EARLY','Daughter of Ninisina and Pabilsag and sister of the dying healer-god Damu, attested as part of the Isin healing-goddess circle.'),
 ('ENT_MES_GATUMDUG','PER_MES_EARLY','Tutelary goddess of Lagash described metaphorically as its mother in Early Dynastic sources, later honored by Gudea who called her his mother and father.'),
 ('ENT_MES_DUMUZI_ABZU','PER_MES_EARLY','Tutelary goddess of Kinunir near Lagash (also called Kinirša), a female counterpart to Dumuzi attested in the Early Dynastic Lagash state pantheon.'),
 ('ENT_MES_NINDARA','PER_MES_EARLY','Local Lagash god and husband of Nanshe, attested in the Early Dynastic Lagash pantheon; Selz regards him as elder brother of Hendursaga.'),
 ('ENT_MES_IGALIMA','PER_MES_EARLY','Son of Ningirsu and Bau, the divine ''door of the throne-room''/E-ninnu, receiving offerings already in Early Dynastic Lagash and named on the Gudea cylinders.'),
 ('ENT_MES_SHULSHAGA','PER_MES_EARLY','Eldest son of Ningirsu and Bau and elder brother of Igalima, attested receiving offerings in Early Dynastic Lagash documents.'),
 ('ENT_MES_SHUL_UTULA','PER_MES_EARLY','''Youngling shepherd,'' personal god of the Ur-Nanshe dynasty of Lagash, named in Early Dynastic royal inscriptions of Eannatum and Entemena.'),
 ('ENT_MES_LUGAL_MARADA','PER_MES_EARLY','City god of Marad, sometimes a manifestation of Ninurta; subject of one of the Temple Hymns, with cult attested from the 3rd millennium.'),
 ('ENT_MES_GIBIL_GIRRA','PER_MES_EARLY','Fire god (Akk. Girra), patron of metalworkers and purification, with earliest attestations in Early Dynastic III administrative texts from Fara and Telloh.'),
 ('ENT_MES_NINILDU','PER_MES_EARLY','Divine carpenter worshiped at Zabalam, attested in the god lists from Abu Salabikh and Fara and in the Early Dynastic Zame Hymns.'),
 ('ENT_MES_NINMUG','PER_MES_EARLY','Divine metalworker/sculptor (''tibira kalamma'') and birth-helper of Ninmah, attested in the Early Dynastic Fara god list with cult at Kisiga and Adab.'),
 ('ENT_MES_NINIMMA','PER_MES_EARLY','Divine scholar/scribe and courtier of Enlil who also assisted at birth; attested among the early Nippur circle and in Enki and Ninmah.'),
 ('ENT_MES_NINKURRA','PER_MES_EARLY','Divine artisan/sculptor of the Enki–Ninhursag generative sequence, mother of Uttu in the Dilmun myth tradition.'),
 ('ENT_MES_NINSHAR','PER_MES_EARLY','Goddess of the Enki–Ninhursag and Enki–Ninmah birth-helper circle; the theophoric name Ur-Ninšar is common in Early Dynastic and Ur III sources.'),
 ('ENT_MES_NINNIGARA','PER_MES_EARLY','Goddess of the niĝar (a birth/temple precinct) linked to birth and healing, attested in the Fara god list and the Early Dynastic Zame Hymns.'),
 ('ENT_MES_NINGIRIMA','PER_MES_EARLY','Major Early Dynastic incantation goddess and divine purifier associated with snakes and sacred-water basins, central to the earliest Sumerian magical tradition.'),
 ('ENT_MES_MES_SANGA_UNUG','PER_MES_EARLY','Warrior god of Uruk''s Kullaba district, ''great ensi of Inanna,'' belonging to the earliest Uruk pantheon and named in the Early Dynastic Zame Hymns.'),
 ('ENT_MES_NINIRIGAL','PER_MES_EARLY','Tutelary goddess of Uruk''s Kullaba district, counted among the chief deities praised in the opening Early Dynastic hymns.'),
 ('ENT_MES_NIRAH','PER_MES_EARLY','Serpent god and messenger of Ishtaran of Der, depicted as a snake; worship attested from the late Early Dynastic period.'),
 ('ENT_MES_NINGIRIDA','PER_MES_UR_III','Wife of the chthonic god Ninazu and mother of Ningishzida, appearing alongside Ninazu from the Ur III period.'),
 ('ENT_MES_NINURA','PER_MES_EARLY','Goddess of the Umma region and wife of Shara, attested only in third-millennium sources before being displaced by Inanna of Zabalam.'),
 ('ENT_MES_NINTI','PER_MES_EARLY','''Lady of the rib/life,'' one of the eight healing deities born of Ninhursag in the Dilmun myth; attested near Ninkasi in a Fara-period document.'),
 ('ENT_MES_NUNGAL','PER_MES_EARLY','Goddess of prisons and divine sifter of the guilty from the innocent, a daughter-in-law of Enlil whose name is attested already in the Early Dynastic period.'),
 ('ENT_EGY_BAT','PER_EGY_EARLY_DYNASTIC','Archaic bovine sky-goddess of the 7th Upper Egyptian nome, depicted as the inward-curling-horned cow head atop the Narmer Palette (Dyn. 0/1) and later absorbed by Hathor.'),
 ('ENT_EGY_MEHIT','PER_EGY_EARLY_DYNASTIC','Lioness goddess of This/Thinis whose recumbent-lioness emblem is attested already in the Early Dynastic period; consort of Anhur (Onuris).'),
 ('ENT_EGY_SED','PER_EGY_EARLY_DYNASTIC','Archaic jackal/wolf-form deity for whom the royal Sed (jubilee) festival is named, attested from the 1st Dynasty and associated with Wepwawet.'),
 ('ENT_EGY_DUNANWI','PER_EGY_OLD_KINGDOM','Falcon tutelary of the 18th Upper Egyptian nome, named in the Pyramid Texts and later largely assimilated to Horus.'),
 ('ENT_EGY_KHENTYIRTY','PER_EGY_OLD_KINGDOM','Falcon god of Letopolis appearing as Khenty-irty (''Foremost of the Two Eyes'')/Khenty-khety; attested from the Old Kingdom and linked to the waxing and waning of celestial light.'),
 ('ENT_EGY_SEPA','PER_EGY_OLD_KINGDOM','Centipede god of Heliopolis invoked against venomous creatures; attested from the Old Kingdom and later identified with Osiris.'),
 ('ENT_EGY_HEDEDET','PER_EGY_OLD_KINGDOM','Scorpion goddess named in the Pyramid Texts, a protective scorpion power later assimilated to Isis.'),
 ('ENT_EGY_KHENTIKHETI','PER_EGY_OLD_KINGDOM','Local god of Athribis (10th Lower Egyptian nome), originally crocodile-form and later falcon-form (Horus-Khenti-kheti), attested from the Old Kingdom.'),
 ('ENT_EGY_SOULS_OF_PE','PER_EGY_OLD_KINGDOM','Falcon-headed ancestral spirits of the predynastic rulers of Pe (Buto) in the Delta, invoked acclaiming the king in the Pyramid Texts.'),
 ('ENT_EGY_SOULS_OF_NEKHEN','PER_EGY_OLD_KINGDOM','Jackal-headed ancestral spirits of the predynastic rulers of Nekhen (Hierakonpolis) in Upper Egypt, paired with the Souls of Pe in the Pyramid Texts.'),
 ('ENT_EGY_IABET','PER_EGY_OLD_KINGDOM','Goddess personifying the East (Iabtet), counterpart of Imentet the West, attested from the Old Kingdom and associated with the rising sun.'),
 ('ENT_EGY_IMENTET','PER_EGY_OLD_KINGDOM','Goddess of the West and the realm of the dead, wearing the West (imnt) emblem on her head, attested from the Old Kingdom and closely linked to Hathor.'),
 ('ENT_EGY_NEBETHETEPET','PER_EGY_OLD_KINGDOM','Heliopolitan goddess (''Mistress of the Offering/Contentment'') personifying the creative hand of Atum, associated with Iusaaset and Hathor from the Old Kingdom onward.'),
 ('ENT_EGY_IUNIT','PER_EGY_MIDDLE_KINGDOM','Local goddess of Hermonthis/Armant (Iuni), a consort of Montu in the Theban region, attested from the Middle Kingdom.'),
 ('ENT_EGY_HENKHISESUI','PER_EGY_OLD_KINGDOM','Personification of the east wind, one of the cardinal-wind deities, attested as a ram- or scarab-form figure and linked to Anhur.'),
 ('ENT_EGY_SERET','PER_EGY_OLD_KINGDOM','Lioness goddess associated with a Delta locality, one of the archaic feline tutelaries grouped with Bastet and Sekhmet.'),
 ('ENT_EGY_AHA','PER_EGY_MIDDLE_KINGDOM','Aha (''the Fighter''), a leonine-dwarf apotropaic deity depicted strangling serpents on Middle Kingdom ''magic wands'', an early antecedent of Bes.'),
 ('ENT_EGY_SEFKHETABWY','PER_EGY_OLD_KINGDOM','''She of the Seven Horns'', a form/aspect of the writing goddess associated with the foundation-ceremony ''stretching of the cord'', attested from the Old Kingdom alongside Seshat.'),
 ('ENT_ELAM_PINIKIR','PER_ELAM_CLASSICAL','Great early Elamite astral goddess titled ''mistress of heaven''; appears in the Old Elamite treaty of Naram-Sin and at Tchoga Zanbil, equated with Ishtar/Ninsianna in god lists.'),
 ('ENT_ELAM_SIMUT','PER_ELAM_CLASSICAL','Elamite herald-god (''god of Elam''), spouse of Manzat, equated with Mesopotamian Nergal and the planet Mars; widely attested in royal inscriptions and An=Anum.'),
 ('ENT_ELAM_NAHHUNTE','PER_ELAM_CLASSICAL','Elamite sun god and guarantor of justice/contracts, counterpart of Mesopotamian Shamash; element in many royal names (e.g. Šutruk-Nahhunte) and attested from Susa.'),
 ('ENT_ELAM_MANZAT','PER_ELAM_CLASSICAL','Rainbow goddess shared between Elam and Mesopotamia; in Elam wife of Simut, worshipped at Susa and Der; attested in Middle Elamite royal inscriptions.'),
 ('ENT_ELAM_RUHURATER','PER_ELAM_CLASSICAL','Creator god whose cult centre was Huhnur; attested from an Ur III inscription of Amar-Sin and in Middle Elamite texts, regarded as a fashioner of humankind.'),
 ('ENT_ELAM_HUTRAN','PER_ELAM_CLASSICAL','Son of Napirisha and Kiririsha in the Tchoga Zanbil / Anshanite theology; invoked in Middle Elamite royal inscriptions for protection of the king.'),
 ('ENT_ELAM_LAGAMAL','PER_ELAM_CLASSICAL','Underworld god of Susa (also worshipped at Mesopotamian Dilbat); in Susian funerary texts the ''advocatus diaboli'' who, with Ishmekarab, attends Inshushinak''s judgment of souls.'),
 ('ENT_ELAM_ISHMEKARAB','PER_ELAM_CLASSICAL','Deity of justice (''he/she has heard the prayer''); in Susian afterlife texts the ''advocatus dei'' who, with Lagamal, escorts the soul before the judge Inshushinak; attested at Susa and Tchoga Zanbil.'),
 ('ENT_ELAM_NARUNDI','PER_ELAM_CLASSICAL','Victory goddess worshipped at Susa c. 2250-1800 BCE (statue dedicated by Puzur-Inshushinak); in Mesopotamian An=Anum reckoned sister of the Sebitti, the ''divine seven of Elam''.'),
 ('ENT_ELAM_NAPRATEP','PER_ELAM_CLASSICAL','Group of ''creator/protector gods'' invoked in Middle Elamite royal inscriptions, notably those of Untash-Napirisha at Tchoga Zanbil.'),
 ('ENT_ELAM_SIASHUM','PER_ELAM_CLASSICAL','Goddess receiving a dedicated chapel/inscription in the sacred precinct of Tchoga Zanbil (Dur-Untash) under Untash-Napirisha.'),
 ('ENT_ELAM_KILAH_SHUPIR','PER_ELAM_CLASSICAL','God honoured by a dedicatory inscription in the Tchoga Zanbil temple complex of Untash-Napirisha.'),
 ('ENT_ELAM_UPURKUBAK','PER_ELAM_CLASSICAL','Goddess with a dedicated chapel at Tchoga Zanbil; named in Middle Elamite inscriptions of Untash-Napirisha.'),
 ('ENT_ELAM_HISHMITIK','PER_ELAM_CLASSICAL','Deity worshipped (frequently paired with Ruhurater) in the Tchoga Zanbil precinct of Untash-Napirisha.'),
 ('ENT_ELAM_TEPTI','PER_ELAM_CLASSICAL','Elamite ''lord'' (tepti/temti) used as a divine epithet and theophoric element (e.g. Tepti-ahar, Temti-Agun) in Sukkalmah- and Middle-Elamite royal names and inscriptions.'),
 ('ENT_ELAM_JABRU','PER_ELAM_CLASSICAL','Listed in Mesopotamian god lists (An=Anum, variant Yabru) as the ''Enlil of Elam''; known only from Mesopotamian texts and not yet attested in indigenous Elamite sources.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_MES_HENDURSAGA','syncretized_with','ENT_MES_ISHUM','high','Hendursaga is equated with Akkadian Ishum in god lists from the Old Babylonian period onward.'),
 ('ENT_MES_HENDURSAGA','member_of','ENT_MES_NANSHE','medium','Hendursaga belongs to the Lagash state pantheon centered on Nanshe''s circle.'),
 ('ENT_MES_HENDURSAGA','presides_over','ENT_PROTECTION','high','He is the divine night-watchman and herald who guards streets at night.'),
 ('ENT_MES_NINEGAL','guardian_of','ENT_PROTECTION','high','''Lady of the Palace'' served as protectress of the royal dynasty and palace.'),
 ('ENT_MES_NINEGAL','identified_with','ENT_MES_INANNA_ISHTAR','low','Ninegal/Belet-ekallim was at times drawn into the orbit of Ishtar in palace cult.'),
 ('ENT_MES_NIN_MARKI','child_of','ENT_MES_NANSHE','high','Nin-MAR.KI is the daughter of Nanshe and Nindara in the Lagash pantheon.'),
 ('ENT_MES_NIN_MARKI','child_of','ENT_MES_NINDARA','high','Her father is Nindara, husband of Nanshe.'),
 ('ENT_MES_NIN_MARKI','presides_over','ENT_ANIMALS','high','She was the divine protector of cattle.'),
 ('ENT_MES_LISIN','child_of','ENT_MES_NINHURSAG','high','Lisin is daughter of Ninhursag and Shulpae.'),
 ('ENT_MES_LISIN','spouse_of','ENT_MES_NINSIKILA','high','Ninsikila is the spouse of Lisin in Early Dynastic sources.'),
 ('ENT_MES_NINSIKILA','spouse_of','ENT_MES_LISIN','high','Ninsikila is consort of Lisin in the Zame Hymns tradition.'),
 ('ENT_MES_ASHGI','child_of','ENT_MES_NINHURSAG','high','Ashgi is son of Ninhursag and Shulpae.'),
 ('ENT_MES_ASHGI','sibling_of','ENT_MES_PANIGINGARRA','high','Ashgi and Panigingarra are both sons of Ninhursag at Adab.'),
 ('ENT_MES_ASHGI','presides_over','ENT_WAR','medium','The Kesh Temple Hymn characterizes Ashgi as a warrior god.'),
 ('ENT_MES_PANIGINGARRA','child_of','ENT_MES_NINHURSAG','high','Panigingarra is son of Ninhursag and Shulpae per An=Anum and the Weidner list.'),
 ('ENT_MES_PANIGINGARRA','identified_with','ENT_MES_NINURTA','low','In late sources he could be equated with Ninurta.'),
 ('ENT_MES_PABILSAG','spouse_of','ENT_MES_NINISINA','high','Pabilsag is the husband of Ninisina.'),
 ('ENT_MES_PABILSAG','identified_with','ENT_MES_NINURTA','low','Pabilsag was at times equated with Ninurta as a warrior god.'),
 ('ENT_MES_PABILSAG','presides_over','ENT_WAR','medium','Pabilsag is fundamentally a warrior god in the early tradition.'),
 ('ENT_MES_NINISINA','spouse_of','ENT_MES_PABILSAG','high','Ninisina is wife of Pabilsag.'),
 ('ENT_MES_NINISINA','parent_of','ENT_MES_DAMU','high','Ninisina is mother of the healer-god Damu.'),
 ('ENT_MES_NINISINA','presides_over','ENT_HEALING','high','Ninisina is the great divine physician of Isin.'),
 ('ENT_MES_NINISINA','syncretized_with','ENT_MES_GULA','high','Ninisina was syncretized with the healing goddess Gula.'),
 ('ENT_MES_GUNURA','child_of','ENT_MES_NINISINA','high','Gunura is daughter of Ninisina and Pabilsag.'),
